params.shaderSource:
shader_type canvas_item;

uniform float speed : hint_range(0.0, 5.0) = 1.0;
uniform float swirl_strength : hint_range(0.0, 20.0) = 6.0;
uniform float ring_count : hint_range(1.0, 30.0) = 8.0;
uniform float saturation : hint_range(0.0, 1.0) = 0.9;
uniform float brightness : hint_range(0.0, 1.0) = 0.95;

vec3 hsv2rgb(vec3 c) {
	vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
	vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
	return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void fragment() {
	vec2 center = vec2(0.5, 0.5);
	vec2 uv = UV - center;
	float dist = length(uv);
	float angle = atan(uv.y, uv.x);
	float swirl = angle + dist * swirl_strength + TIME * speed;
	float hue = fract(swirl / 6.2832 + dist * ring_count);
	vec3 color = hsv2rgb(vec3(hue, saturation, brightness));
	float vignette = 1.0 - smoothstep(0.3, 0.7, dist);
	COLOR = vec4(color * (0.6 + 0.4 * vignette), 1.0);
}
